const blockByName = new Map(mathmlBlocks.map((block) => [block.name, block]));

/**
 * The generated fixtures: every block of `mathmlBlocks` in exactly one group.
 */
export const mathmlGroups: readonly MathmlGroup[] = groupPlans.map((group) => ({
  blocks: group.blocks.flatMap((name) => blockByName.get(name) ?? []),
  name: group.name,
  version: group.version,
}));
